import { beforeEach, describe, expect, it, vi } from "vitest";
import type {
  HandleUploadOptions,
  HandleUploadPresignedOptions,
} from "@vercel/blob/client";
const mocks = vi.hoisted(() => ({
  options: {} as HandleUploadOptions,
  presignedOptions: {} as HandleUploadPresignedOptions,
  issueSignedToken: vi.fn(),
  payload: null as
    Parameters<NonNullable<HandleUploadOptions["onUploadCompleted"]>>[0] | null,
  auth: vi.fn(),
  user: vi.fn(),
  owner: vi.fn(),
  del: vi.fn(),
  attachment: vi.fn(),
  lock: vi.fn(),
  createAttachment: vi.fn(),
  updateAttachment: vi.fn(),
}));
vi.mock("@/auth", () => ({ auth: mocks.auth }));
vi.mock("@/lib/db", () => ({
  db: {
    user: { findFirst: mocks.user, findUnique: mocks.owner },
    attachment: {
      findFirst: mocks.attachment,
      updateMany: mocks.updateAttachment,
    },
    $transaction: (work: (tx: unknown) => unknown) =>
      work({
        user: { findFirst: mocks.user, findUnique: mocks.owner },
        attachment: {
          findFirst: mocks.attachment,
          create: mocks.createAttachment,
        },
        $queryRaw: mocks.lock,
      }),
  },
}));
vi.mock("@vercel/blob", () => ({
  del: mocks.del,
  issueSignedToken: mocks.issueSignedToken,
}));
vi.mock("@vercel/blob/client", () => ({
  handleUpload: async (options: HandleUploadOptions) => {
    mocks.options = options;
    if (mocks.payload) await options.onUploadCompleted!(mocks.payload);
    return { type: "test" };
  },
  handleUploadPresigned: async (options: HandleUploadPresignedOptions) => {
    mocks.presignedOptions = options;
    return { type: "test" };
  },
}));
import { POST } from "@/app/api/resume/blob/route";
import { DELETION_DRAIN_MS } from "@/lib/account";
import { MAX_PDF_BYTES } from "@/lib/validation";
const userId = "f5a05555-5732-4463-b29e-d4cdfef33354";
const pathname = `resumes/${userId}/f5a05555-5732-4463-b29e-d4cdfef33355.pdf`;
describe("Blob deletion boundaries after service signature verification", () => {
  beforeEach(async () => {
    vi.clearAllMocks();
    mocks.payload = null;
    mocks.attachment.mockResolvedValue(null);
    mocks.createAttachment.mockResolvedValue({ id: "rejected" });
    vi.stubEnv("BLOB_READ_WRITE_TOKEN", "fake-test-token");
    mocks.owner.mockResolvedValue(null);
    await POST(
      new Request("http://localhost/api/resume/blob", {
        method: "POST",
        headers: { origin: "http://localhost" },
        body: "{}",
      }),
    );
  });
  it("does not issue upload authorization for a disabled account", async () => {
    mocks.auth.mockResolvedValue({ user: { id: userId } });
    mocks.user.mockResolvedValue(null);
    await expect(
      mocks.options.onBeforeGenerateToken(pathname, null, false),
    ).rejects.toThrow("unavailable");
  });
  it("issues a tenant-bound token for at most ten minutes", async () => {
    mocks.auth.mockResolvedValue({ user: { id: userId } });
    mocks.user.mockResolvedValue({ id: userId });
    const now = Date.now();
    const clock = vi.spyOn(Date, "now").mockReturnValue(now);
    try {
      const token = await mocks.options.onBeforeGenerateToken(
        pathname,
        null,
        false,
      );
      expect(JSON.parse(token.tokenPayload!)).toEqual({ userId });
      expect(token.validUntil).toBe(now + 600000);
      expect(token.allowOverwrite).toBe(false);
    } finally {
      clock.mockRestore();
    }
  });
  it("rejects suspended owners under the owner lock and cleans up only unactivated uploads", async () => {
    mocks.auth.mockResolvedValue({ user: { id: userId } });
    mocks.user.mockResolvedValue(null);
    await expect(
      mocks.options.onBeforeGenerateToken(pathname, null, false),
    ).rejects.toThrow("unavailable");
    expect(mocks.lock).toHaveBeenCalled();
    expect(mocks.user).toHaveBeenCalledWith(
      expect.objectContaining({
        where: { id: userId, deletionRequestedAt: null, isSuspended: false },
      }),
    );
    mocks.owner.mockResolvedValue({
      isSuspended: true,
      deletionRequestedAt: null,
    });
    const payload = {
      tokenPayload: JSON.stringify({ userId }),
      blob: {
        pathname,
        url: "https://private.blob.vercel-storage.com/owned",
        downloadUrl: "https://private.blob.vercel-storage.com/owned",
        contentType: "application/pdf",
        contentDisposition: "attachment",
        etag: "test",
      },
    };
    await mocks.options.onUploadCompleted!(payload);
    expect(mocks.del).toHaveBeenCalledTimes(1);
    mocks.attachment.mockResolvedValue({ id: "retained" });
    await mocks.options.onUploadCompleted!(payload);
    expect(mocks.del).toHaveBeenCalledTimes(1);
  });
  it("preserves an already activated PDF during the worker drain window", async () => {
    mocks.owner.mockResolvedValue({ deletionRequestedAt: new Date() });
    await mocks.options.onUploadCompleted!({
      tokenPayload: JSON.stringify({ userId }),
      blob: {
        pathname,
        url: "https://private.blob.vercel-storage.com/owned",
        downloadUrl: "https://private.blob.vercel-storage.com/owned",
        contentType: "application/pdf",
        contentDisposition: "attachment",
        etag: "test",
      },
    });
    expect(mocks.del).not.toHaveBeenCalled();
  });
  it.each([DELETION_DRAIN_MS - 1, DELETION_DRAIN_MS])(
    "uses the 15-minute drain boundary for a callback at %i ms",
    async (elapsed) => {
      const now = Date.now();
      const clock = vi.spyOn(Date, "now").mockReturnValue(now);
      try {
        expect(DELETION_DRAIN_MS).toBe(15 * 60 * 1000);
        mocks.owner.mockResolvedValue({
          deletionRequestedAt: new Date(now - elapsed),
        });
        await mocks.options.onUploadCompleted!({
          tokenPayload: JSON.stringify({ userId }),
          blob: {
            pathname,
            url: "https://private.blob.vercel-storage.com/owned",
            downloadUrl: "https://private.blob.vercel-storage.com/owned",
            contentType: "application/pdf",
            contentDisposition: "attachment",
            etag: "test",
          },
        });
        expect(mocks.del).toHaveBeenCalledTimes(
          elapsed < DELETION_DRAIN_MS ? 0 : 1,
        );
      } finally {
        clock.mockRestore();
      }
    },
  );
  it("returns a retryable service response when late-upload removal fails", async () => {
    mocks.user.mockResolvedValue(null);
    mocks.del.mockRejectedValueOnce(new Error("storage outage"));
    mocks.payload = {
      tokenPayload: JSON.stringify({ userId }),
      blob: {
        pathname,
        url: "https://private.blob.vercel-storage.com/owned",
        downloadUrl: "https://private.blob.vercel-storage.com/owned",
        contentType: "application/pdf",
        contentDisposition: "attachment",
        etag: "test",
      },
    };
    const response = await POST(
      new Request("http://localhost/api/resume/blob", {
        method: "POST",
        body: "{}",
      }),
    );
    expect(response.status).toBe(503);
  });
  it("removes late unactivated uploads for missing accounts and propagates storage failures for retries", async () => {
    mocks.user.mockResolvedValue(null);
    const payload = {
      tokenPayload: JSON.stringify({ userId }),
      blob: {
        pathname,
        url: "https://private.blob.vercel-storage.com/owned",
        downloadUrl: "https://private.blob.vercel-storage.com/owned",
        contentType: "application/pdf",
        contentDisposition: "attachment",
        etag: "test-etag",
      },
    };
    await mocks.options.onUploadCompleted!(payload);
    expect(mocks.del).toHaveBeenCalledWith(
      payload.blob.pathname,
      expect.objectContaining({ abortSignal: expect.any(AbortSignal) }),
    );
    mocks.del.mockRejectedValueOnce(new Error("retry storage"));
    await expect(mocks.options.onUploadCompleted!(payload)).rejects.toThrow(
      "cleanup requires retry",
    );
  });
});

describe("OIDC presigned resume uploads", () => {
  it("issues a short-lived, owner-scoped PDF delegation", async () => {
    vi.stubEnv("BLOB_READ_WRITE_TOKEN", "");
    vi.stubEnv("BLOB_STORE_ID", "store_test");
    mocks.auth.mockResolvedValue({ user: { id: userId } });
    mocks.user.mockResolvedValue({ id: userId });
    mocks.issueSignedToken.mockResolvedValue({
      delegationToken: "delegation",
      clientSigningToken: "signing",
      validUntil: Date.now() + 600000,
    });
    await POST(
      new Request("http://localhost/api/resume/blob", {
        method: "POST",
        body: "{}",
        headers: { origin: "http://localhost" },
      }),
    );
    const result = await mocks.presignedOptions.getSignedToken(
      pathname,
      null,
      false,
    );
    expect(mocks.issueSignedToken).toHaveBeenCalledWith(
      expect.objectContaining({
        pathname,
        operations: ["put"],
        allowedContentTypes: ["application/pdf"],
        maximumSizeInBytes: MAX_PDF_BYTES,
      }),
    );
    expect(result.urlOptions).toEqual(
      expect.objectContaining({
        allowOverwrite: false,
        addRandomSuffix: false,
        tokenPayload: JSON.stringify({ userId }),
      }),
    );
    await expect(
      mocks.presignedOptions.getSignedToken(
        `resumes/${crypto.randomUUID()}/${crypto.randomUUID()}.pdf`,
        null,
        false,
      ),
    ).rejects.toThrow("Unauthorized");
    vi.unstubAllEnvs();
  });
});
